"use client";

import React from "react";
import { motion } from "framer-motion";
import { BRAND, FONT } from "@/lib/brand";

interface ProductBreadcrumbProps {
  feature: string;
}

export function ProductBreadcrumb({ feature }: ProductBreadcrumbProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6 }}
      style={{
        display: "flex",
        alignItems: "center",
        gap: 12,
        marginBottom: 28,
      } as React.CSSProperties}
    >
      <a
        href="/"
        style={{
          fontFamily: FONT.sans,
          fontSize: 11,
          fontWeight: 600,
          color: BRAND.stoneLight,
          letterSpacing: "0.18em",
          textTransform: "uppercase",
          textDecoration: "none",
        } as React.CSSProperties}
      >
        InkOS
      </a>

      <span
        style={{
          fontFamily: FONT.sans,
          fontSize: 11,
          color: BRAND.stoneLight,
        } as React.CSSProperties}
      >
        /
      </span>

      <a
        href="/product"
        style={{
          fontFamily: FONT.sans,
          fontSize: 11,
          fontWeight: 600,
          color: BRAND.stoneLight,
          letterSpacing: "0.18em",
          textTransform: "uppercase",
          textDecoration: "none",
        } as React.CSSProperties}
      >
        Product
      </a>

      <span
        style={{
          fontFamily: FONT.sans,
          fontSize: 11,
          color: BRAND.stoneLight,
        } as React.CSSProperties}
      >
        /
      </span>

      <span
        style={{
          fontFamily: FONT.sans,
          fontSize: 11,
          fontWeight: 700,
          color: BRAND.onyx,
          letterSpacing: "0.18em",
          textTransform: "uppercase",
        } as React.CSSProperties}
      >
        {feature}
      </span>
    </motion.div>
  );
}

"use client";

import React from "react";
import { motion } from "framer-motion";
import { ArrowRight, ArrowUpRight } from "lucide-react";
import { BRAND, FONT, SHADOW } from "@/lib/brand";
import { ProductBreadcrumb } from "@/components/product/product-breadcrumb";

interface ProductHeroProps {
  feature: string;
  headline: string;
  italicWord: string;
  subhead: string;
  primaryCTA?: { label: string; href: string };
  secondaryCTA?: { label: string; href: string };
  dashboard: React.ReactNode;
}

const defaultPrimary = {
  label: "Start free trial",
  href: "https://inkos.up.railway.app/signup",
};

const defaultSecondary = {
  label: "See it in motion",
  href: "/book-a-demo",
};

function buildHeadlineParts(headline: string, italicWord: string) {
  const idx = headline.indexOf(italicWord);
  if (idx === -1) {
    return { before: headline, italic: "", after: "" };
  }
  return {
    before: headline.slice(0, idx),
    italic: italicWord,
    after: headline.slice(idx + italicWord.length),
  };
}

export function ProductHero({
  feature,
  headline,
  italicWord,
  subhead,
  primaryCTA = defaultPrimary,
  secondaryCTA = defaultSecondary,
  dashboard,
}: ProductHeroProps) {
  const { before, italic, after } = buildHeadlineParts(headline, italicWord);

  return (
    <section
      style={{
        background: BRAND.bone,
        position: "relative",
        overflow: "hidden",
        paddingTop: 140,
        paddingBottom: 80,
      } as React.CSSProperties}
    >
      {/* Background grid texture */}
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          opacity: 0.4,
          pointerEvents: "none",
          backgroundImage: `linear-gradient(${BRAND.border} 1px, transparent 1px), linear-gradient(90deg, ${BRAND.border} 1px, transparent 1px)`,
          backgroundSize: "80px 80px",
          maskImage:
            "radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%)",
        } as React.CSSProperties}
      />

      <div
        style={{
          maxWidth: 1280,
          margin: "0 auto",
          padding: "0 32px",
          position: "relative",
        } as React.CSSProperties}
      >
        <ProductBreadcrumb feature={feature} />

        <div style={{ maxWidth: 920 } as React.CSSProperties}>
          <motion.h1
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
            style={{
              fontFamily: FONT.serif,
              fontSize: "clamp(56px, 8vw, 112px)",
              lineHeight: 0.95,
              letterSpacing: "-0.03em",
              color: BRAND.onyx,
              fontWeight: 400,
              marginBottom: 28,
              margin: "0 0 28px 0",
            } as React.CSSProperties}
          >
            {before}
            <span
              style={{
                fontStyle: "italic",
                color: BRAND.rust,
              } as React.CSSProperties}
            >
              {italic}
            </span>
            {after}
          </motion.h1>

          <motion.p
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.65, delay: 0.12, ease: [0.22, 1, 0.36, 1] }}
            style={{
              fontFamily: FONT.sans,
              fontSize: 19,
              lineHeight: 1.55,
              color: BRAND.stoneDark,
              maxWidth: 720,
              marginBottom: 36,
            } as React.CSSProperties}
          >
            {subhead}
          </motion.p>

          <motion.div
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.22, ease: [0.22, 1, 0.36, 1] }}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 14,
              flexWrap: "wrap",
            } as React.CSSProperties}
          >
            <a
              href={primaryCTA.href}
